# 32x32 byte matrix multiply, ikj loop order (MMB).
#   A at 0x2000, B at 0x3000, C at 0x4000.  Generated by
#   scripts/generate_matmul.py — DO NOT EDIT BY HAND.

_start:
    lui  sp, 0xC
    lui  s0, 0x2
    lui  s1, 0x3
    lui  s2, 0x4
    addi s3, x0, 32

    addi t0, x0, 0
    addi t1, x0, 1024
zero_c:
    bge  t0, t1, zero_done
    add  t2, s2, t0
    sb   x0, 0(t2)
    addi t0, t0, 1
    jal  x0, zero_c
zero_done:

    addi s4, x0, 0
i_loop:
    bge  s4, s3, mm_end
    addi s7, x0, 0
k_loop:
    bge  s7, s3, k_end
    slli t0, s4, 5
    add  t0, t0, s7
    add  t0, s0, t0
    lb   s8, 0(t0)
    addi s5, x0, 0
j_loop:
    bge  s5, s3, j_end
    slli t1, s7, 5
    add  t1, t1, s5
    add  t1, s1, t1
    lb   a1, 0(t1)
    add  a0, s8, x0
    jal  ra, mul
    slli t0, s4, 5
    add  t0, t0, s5
    add  t0, s2, t0
    lb   t2, 0(t0)
    add  t2, t2, a0
    sb   t2, 0(t0)
    addi s5, s5, 1
    jal  x0, j_loop
j_end:
    addi s7, s7, 1
    jal  x0, k_loop
k_end:
    addi s4, s4, 1
    jal  x0, i_loop
mm_end:
    ebreak

mul:
    addi t6, x0, 0
    andi a1, a1, 0xff
    beq  a1, x0, mul_done
mul_loop:
    add  t6, t6, a0
    addi a1, a1, -1
    bne  a1, x0, mul_loop
mul_done:
    add  a0, t6, x0
    jalr x0, 0(ra)
